CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, password_hash VARCHAR(180) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'customer', address VARCHAR(200) NOT NULL DEFAULT '', phone VARCHAR(40) NOT NULL DEFAULT '', reset_code VARCHAR(20) DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, number VARCHAR(20) UNIQUE NOT NULL, kind VARCHAR(20) NOT NULL, balance_cents BIGINT NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'USD', FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE beneficiaries (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, name VARCHAR(100) NOT NULL, account_number VARCHAR(20) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE transactions (id INT AUTO_INCREMENT PRIMARY KEY, from_account INT NOT NULL, to_account INT NOT NULL, amount_cents INT NOT NULL, memo VARCHAR(200) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(from_account) REFERENCES accounts(id), FOREIGN KEY(to_account) REFERENCES accounts(id));
CREATE TABLE notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, message VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE support_messages (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, subject VARCHAR(120) NOT NULL, message TEXT NOT NULL, response TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
